// The done-when check for runbook step P1.3: past USTP votes reproduce their published results
// exactly, abstention rules included. Each fixture's published.json is transcribed by hand from
// the party's report (cited in its source.md), never generated by this engine.
import { describe, expect, it } from 'vitest';
import { canonicalize } from './canonical-json.js';
import { tallyElection } from './tally.js';
import { SEED } from './test-support/ballots.js';
import {
  ballotsFromPublishedCounts,
  decimalsOf,
  percent,
  readFixture,
  type Published,
  type PublishedContest,
} from './test-support/published.js';
import type { Ballot, ContestResult, ElectionDefinition } from './types.js';

function expectMatchesPublished(result: ContestResult, published: PublishedContest) {
  expect(result.method).toBe(published.method);
  if (result.method === 'proposal' && published.method === 'proposal') {
    const { yes, no, abstain } = result.counts;
    expect({ yes, no, abstain }).toEqual(published.counts);
    // USTP's shares are of everyone who answered, abstentions included.
    for (const choice of ['yes', 'no', 'abstain'] as const) {
      const printed = published.percent[choice];
      expect(percent(result.counts[choice], yes + no + abstain, decimalsOf(printed))).toBe(printed);
    }
    expect(result.outcome).toBe(published.outcome);
  } else if (result.method === 'choose-n' && published.method === 'choose-n') {
    expect(result.seatDraw).toBeUndefined();
    for (const p of published.tallies) {
      const t = result.tallies.find((x) => x.candidate === p.candidate);
      expect(t?.votes).toBe(p.votes);
      // The floor's denominator is every ballot cast, including ballots that left this blank.
      expect(percent(p.votes, result.ballots, decimalsOf(p.percent))).toBe(p.percent);
      expect(t?.elected).toBe(p.included);
    }
  } else if (result.method === 'instant-runoff' && published.method === 'instant-runoff') {
    expect(result.rounds).toHaveLength(published.rounds.length);
    published.rounds.forEach((p, i) => {
      const round = result.rounds[i]!;
      expect(round.tieBreak).toBeUndefined();
      expect(round.continuing).toBe(p.continuing);
      expect(Object.fromEntries(round.tallies.map((t) => [t.candidate, t.votes]))).toEqual(
        Object.fromEntries(p.tallies.map((t) => [t.candidate, t.votes])),
      );
      // Shares are of continuing ballots in that round.
      for (const t of p.tallies) {
        expect(percent(t.votes, round.continuing, decimalsOf(t.percent))).toBe(t.percent);
      }
      expect(round.eliminated).toBe(p.eliminated);
    });
    expect(result.winner).toBe(published.winner);
  } else {
    throw new Error('method mismatch');
  }
}

function rankSummary(ballots: Ballot[], contest: string, candidates: string[]) {
  const summary = Object.fromEntries(candidates.map((c) => [c, candidates.map(() => 0)]));
  for (const b of ballots) {
    (b.contests[contest] as string[] | undefined)?.forEach((c, rank) => summary[c]![rank]!++);
  }
  return summary;
}

function expectCanonicalOrder(ballots: Ballot[]) {
  const lines = ballots.map(canonicalize);
  expect(lines).toEqual([...lines].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)));
}

describe('Platform Vote 9 (February 17 to March 10, 2025)', () => {
  const election = readFixture<ElectionDefinition>('platform-vote-9', 'election.json');
  const published = readFixture<Published>('platform-vote-9', 'published.json');
  const results = tallyElection(election, ballotsFromPublishedCounts(election, published), SEED);

  it('counts 68 ballots', () => {
    expect(results.ballots).toBe(published.ballots);
  });

  results.contests.forEach((result) => {
    const p = published.contests[result.contest]!;
    it(`Question ${p.question}: ${p.title}`, () => expectMatchesPublished(result, p));
  });

  for (const [id, p] of Object.entries(published.pending ?? {})) {
    it.todo(`Question ${p.question} (${id}) is pending: ${p.missing}`);
  }

  it('covers every question on the ballot', () => {
    const ids = [...election.contests.map((c) => c.id), ...Object.keys(published.pending ?? {})];
    expect(ids.sort()).toEqual(
      Array.from({ length: 20 }, (_, i) => `q${String(i + 1).padStart(2, '0')}`),
    );
  });
});

for (const [id, label] of [
  ['primary-2019', '2019 Electronic Primary (September 21 to 30, 2019)'],
  ['primary-2023', '2023 Electronic Primary (May 14 to 22, 2023)'],
] as const) {
  describe(label, () => {
    const election = readFixture<ElectionDefinition>(id, 'election.json');
    const published = readFixture<Published>(id, 'published.json');
    const ballots = readFixture<Ballot[]>(id, 'ballots.json');
    const contest = election.contests[0]!;
    const p = published.contests[contest.id]!;

    it('holds anonymous ballots in canonical sorted order', () => {
      expect(ballots).toHaveLength(published.ballots);
      for (const b of ballots) expect(Object.keys(b)).toEqual(['contests']);
      expectCanonicalOrder(ballots);
    });

    it('reproduces the published summary of rankings', () => {
      if (p.method !== 'instant-runoff' || contest.method !== 'instant-runoff') throw new Error();
      const expected = structuredClone(p.rankSummary!);
      if (id === 'primary-2023') {
        // One ballot ranks Twedt 1 and Ross 3 with no 2nd choice. USTP's summary counts its
        // Ross as a 3rd choice; the fixture closes the gap, making it a 2nd (see source.md).
        expected.ross![1]!++;
        expected.ross![2]!--;
      }
      expect(rankSummary(ballots, contest.id, contest.candidates)).toEqual(expected);
    });

    it('reproduces every published round and the winner', () => {
      const results = tallyElection(election, ballots, SEED);
      expect(results.contests[0]!.method).toBe('instant-runoff');
      expectMatchesPublished(results.contests[0]!, p);
    });
  });
}
